import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{"docLocale":"en","counterpart":"/getting-started/quickstart","contentType":"guide","prev":{"text":"Project documentation","link":"/en/docs/"},"next":{"text":"Lab and asset library","link":"/en/guides/lab-viewer"}},"headers":[],"relativePath":"en/getting-started/quickstart.md","filePath":"en/getting-started/quickstart.md"}'),n={name:"en/getting-started/quickstart.md"};function r(o,e,l,d,h,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Goal: start Lab Word and check HTTP and Web access. Current Viewer validation comes from a <a href="./../guides/lab-viewer">separate preview</a>. Record acceptance of the production Lab integration separately.</p><h2 id="_1-install-and-start" tabindex="-1">1. Install And Start <a class="header-anchor" href="#_1-install-and-start" aria-label="Permalink to &quot;1. Install And Start&quot;">​</a></h2><p>Install Docker with Compose. Use these tool versions:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Version</th><th>Source</th></tr></thead><tbody><tr><td>Rust</td><td>1.96.0</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/23ad3a3f049ce83ce31f9a3a600361ac813c015f/rust-toolchain.toml" target="_blank" rel="noreferrer">Rust toolchain</a></td></tr><tr><td>Node</td><td>24.18.0</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/23ad3a3f049ce83ce31f9a3a600361ac813c015f/.node-version" target="_blank" rel="noreferrer">Node version</a></td></tr><tr><td>pnpm</td><td>11.17.0</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/23ad3a3f049ce83ce31f9a3a600361ac813c015f/package.json" target="_blank" rel="noreferrer">Package configuration</a></td></tr><tr><td>just</td><td>1.58.0</td><td><a href="https://github.com/CaiZongyuan/labworld/blob/23ad3a3f049ce83ce31f9a3a600361ac813c015f/.tool-versions" target="_blank" rel="noreferrer">Tool versions</a></td></tr></tbody></table><p>Run these commands to clone the repository and start development:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/CaiZongyuan/labworld.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labworld</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Run project commands from the repository root. The first launch downloads dependencies and compiles Rust. The development script starts PostgreSQL, Redis, RustFS and Mailpit. It applies migrations and initializes storage. It then starts the API, Worker and Web. The script writes data to local development volumes.</p><p>Default settings come from <a href="https://github.com/CaiZongyuan/labworld/blob/23ad3a3f049ce83ce31f9a3a600361ac813c015f/.env.example" target="_blank" rel="noreferrer">.env.example</a>. To change them, create an untracked <code>.env</code> file. See the <a href="./../reference/config">generated API configuration</a>.</p><h2 id="_2-observe-the-result" tabindex="-1">2. Observe The Result <a class="header-anchor" href="#_2-observe-the-result" aria-label="Permalink to &quot;2. Observe The Result&quot;">​</a></h2><p>Keep development running. Run these commands in another terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/system/status</span></span></code></pre></div><p>Each response should return HTTP 200 and include <code>x-request-id</code>.</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Expected information</th></tr></thead><tbody><tr><td><code>/health/live</code></td><td>The API process is running.</td></tr><tr><td><code>/health/ready</code></td><td>Dependencies and migrations are ready.</td></tr><tr><td><code>/api/v1/system/status</code></td><td>The current system state.</td></tr></tbody></table><p>Passwords must contain 12–128 characters.</p><ol><li>Open <a href="http://127.0.0.1:5173/register" target="_blank" rel="noreferrer">http://127.0.0.1:5173/register</a>.</li><li>Create a development account.</li></ol><p>The first account is Owner. Later accounts are Members. Read development email at <a href="http://127.0.0.1:8025" target="_blank" rel="noreferrer">http://127.0.0.1:8025</a>.</p><p>Use the existing platform to check authentication and business operations. Lab behavior depends on the integration acceptance for its version.</p><h2 id="_3-check-dependency-failure-and-recovery" tabindex="-1">3. Check Dependency Failure And Recovery <a class="header-anchor" href="#_3-check-dependency-failure-and-recovery" aria-label="Permalink to &quot;3. Check Dependency Failure And Recovery&quot;">​</a></h2><p>Run this failure check only in your own development environment.</p><ol><li>Stop PostgreSQL:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db-down</span></span></code></pre></div><ol start="2"><li>Check readiness:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span></code></pre></div><p><code>/health/ready</code> should return 503. <code>/health/live</code> should still return 200.</p><ol start="3"><li>Start PostgreSQL:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span></span></code></pre></div><ol start="4"><li>Check readiness again:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span></code></pre></div><p><code>/health/ready</code> should return 200 again.</p><p>If migrations do not match, first check the source revision. Then run <code>just migrate</code>. API startup does not apply migrations automatically.</p><p>After you add SQL migrations:</p><ol><li>Run <code>just migrate</code>.</li><li>Restart development.</li></ol><p>The restart updates the migration set in the binary.</p><h2 id="stop-and-continue" tabindex="-1">Stop And Continue <a class="header-anchor" href="#stop-and-continue" aria-label="Permalink to &quot;Stop And Continue&quot;">​</a></h2><p>Press <code>Ctrl+C</code> to stop the API, Worker and Web. Run <code>just services-down</code> to stop containers. This command keeps the development volumes.</p><p>If you change the API port, update <code>APP_BIND</code>. Set <code>VITE_API_PROXY</code> to a reachable address for that API.</p><p>If you change the Web address, set <code>APP_ORIGIN</code> to the browser origin, including scheme, host and port.</p><p>If you change the database port, update both <code>POSTGRES_PORT</code> and <code>DATABASE_URL</code>.</p><p>Next, <a href="./../guides/lab-viewer">run the Lab Viewer preview</a> or read the <a href="./../architecture/project-structure">project structure</a>.</p><p>To open the documentation:</p><ol><li>Run <code>just docs</code> from the repository root.</li><li>Open <a href="http://127.0.0.1:5174/labworld/en/docs/" target="_blank" rel="noreferrer">http://127.0.0.1:5174/labworld/en/docs/</a>.</li></ol><hr><p>Source version：<code>23ad3a3f049c</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/23ad3a3f049ce83ce31f9a3a600361ac813c015f/docs/getting-started/quickstart.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,44)])])}const u=t(n,[["render",r]]);export{k as __pageData,u as default};
